/// The current time as stored in our timestamp columns: UTC, ISO 8601, with
/// milliseconds (`2026-11-16T20:15:13.123Z`).
pub fn now() -> String {
    sea_orm::prelude::ChronoUtc::now()
        .format("%Y-%m-%dT%H:%M:%S%.3fZ")
        .to_string()
}

/// Returns the running SQLite engine version (for example `3.46.0`).
pub async fn sqlite_version(db: &DatabaseConnection) -> Result<String, DbErr> {
    let row = db
        .query_one_raw(Statement::from_string(
            db.get_database_backend(),
            "SELECT sqlite_version() AS version".to_owned(),
        ))
        .await?;
    match row {
        Some(row) => row.try_get("", "version"),
        None => Ok(String::new()),
    }
}

/// Opens `unseenarr.db` in `data_dir` (WAL mode, foreign keys on), creates it if
/// it is missing, and applies every pending migration.
pub async fn connect(data_dir: &Path) -> Result<DatabaseConnection, DbErr> {
    let db = open(data_dir).await?;
    migration::Migrator::up(&db, None).await?;
    profiles::seed_defaults(&db).await?;
    Ok(db)
}

async fn open(data_dir: &Path) -> Result<DatabaseConnection, DbErr> {
    let options = SqliteConnectOptions::new()
        .filename(data_dir.join("unseenarr.db"))
        .create_if_missing(true)
        .journal_mode(SqliteJournalMode::Wal)
        .foreign_keys(true);
    let pool = SqlitePoolOptions::new()
        .connect_with(options)
        .await
        .map_err(|error| DbErr::Conn(RuntimeErr::SqlxError(error.into())))?;
    Ok(SqlxSqliteConnector::from_sqlx_sqlite_pool(pool))
}

